package io.invenlio.sales;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.LocalDate;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/sales-orders")@SecurityRequirement(name="bearerAuth")class SalesOrderController{private final SalesOrderService service;SalesOrderController(SalesOrderService s){service=s;}@Operation(summary="Create a draft sales order",description="Snapshots customer and warehouse identity; no inventory movement or reservation occurs.")@PostMapping SalesOrderService.OrderView create(@Valid@RequestBody Create r){return service.create(r.command());}@Operation(summary="List sales orders",description="Tenant-scoped filters, bounded pages and allow-listed sorting.")@GetMapping List<SalesOrderService.OrderView>list(@RequestParam(required=false)String orderNumber,@RequestParam(required=false)UUID customerId,@RequestParam(required=false)UUID warehouseId,@RequestParam(required=false)String status,@RequestParam(required=false)LocalDate createdFrom,@RequestParam(required=false)LocalDate createdTo,@RequestParam(required=false)LocalDate requestedFrom,@RequestParam(required=false)LocalDate requestedTo,@RequestParam(required=false)String q,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String sort){return service.list(orderNumber,customerId,warehouseId,status,createdFrom,createdTo,requestedFrom,requestedTo,q,page,size,sort);}@GetMapping("/{id}")SalesOrderService.OrderView get(@PathVariable UUID id){return service.get(id);}@Operation(summary="Update draft fulfillment and destination details")@PatchMapping("/{id}")SalesOrderService.OrderView update(@PathVariable UUID id,@Valid@RequestBody Update r){return service.update(id,r.command(),r.version);}@PostMapping("/{id}/lines")SalesOrderService.LineView add(@PathVariable UUID id,@Valid@RequestBody LineCreate r){return service.addLine(id,r.command());}@PatchMapping("/{id}/lines/{lineId}")SalesOrderService.LineView updateLine(@PathVariable UUID id,@PathVariable UUID lineId,@Valid@RequestBody LineUpdate r){return service.updateLine(id,lineId,new SalesOrderService.LineCommand(null,r.quantity,r.unitPrice),r.version);}@DeleteMapping("/{id}/lines/{lineId}")void remove(@PathVariable UUID id,@PathVariable UUID lineId,@RequestParam long version){service.removeLine(id,lineId,version);}@Operation(summary="Confirm a non-empty draft",description="Validates active customer, warehouse and variants. Confirmation makes no stock change.")@PostMapping("/{id}/confirm")SalesOrderService.OrderView confirm(@PathVariable UUID id,@RequestBody Version r){return service.confirm(id,r.version);}@Operation(summary="Allocate remaining quantity",description="Creates no-expiry SALES_ORDER_LINE inventory reservations using ATP, FEFO, and deterministic serial/location ordering. Partial allocation is supported and no physical movement occurs.")@PostMapping("/{id}/allocate")SalesOrderService.OrderView allocate(@PathVariable UUID id){return service.allocate(id);}@Operation(summary="Cancel and atomically release all active inventory reservations")@PostMapping("/{id}/cancel")SalesOrderService.OrderView cancel(@PathVariable UUID id,@Valid@RequestBody Cancel r){return service.cancel(id,r.version,r.reason);}
 record Create(@NotNull UUID customerId,@NotNull UUID warehouseId,String currency,@Size(max=120)String customerReference,LocalDate requestedDeliveryDate,@Size(max=1000)String shippingAddress,@Size(max=1000)String billingAddress){SalesOrderService.Create command(){return new SalesOrderService.Create(customerId,warehouseId,currency,customerReference,requestedDeliveryDate,shippingAddress,billingAddress);}}record Update(@NotNull UUID warehouseId,@Size(max=120)String customerReference,LocalDate requestedDeliveryDate,@NotBlank@Size(max=1000)String shippingAddress,@Size(max=1000)String billingAddress,@PositiveOrZero long version){SalesOrderService.Update command(){return new SalesOrderService.Update(warehouseId,customerReference,requestedDeliveryDate,shippingAddress,billingAddress);}}record LineCreate(@NotNull UUID variantId,@NotBlank String quantity,@NotBlank String unitPrice){SalesOrderService.LineCommand command(){return new SalesOrderService.LineCommand(variantId,quantity,unitPrice);}}record LineUpdate(@NotBlank String quantity,@NotBlank String unitPrice,@PositiveOrZero long version){}record Version(@PositiveOrZero long version){}record Cancel(@PositiveOrZero long version,@NotBlank@Size(max=500)String reason){}
}
